%root_path = fileparts(mfilename("fullpath"));
%root_path = pwd;

% retrieve selected cuts used for further fitting
[NG_FFCutsFits,CutFitFileNG] = recover_selected_cuts('NG_FFCutsFits','e:\SHARE\Fe\Data\analysis\07_fit_with_multicut_allJ\sel_cuts');

%%
fn = fieldnames(NG_FFCutsFits);
nf = 11 %[output:888861f2]
%for i = 11:numel(fn)
%selectCuts = fn{nf};
selectCuts = 'Ei800_off110NGminFF' %[output:3b59efcf]
if ismember(selectCuts(1:3),{'msk','dat'})||...
        contains(selectCuts,'all_fit_par')
    %continue
    error('Can not fit field: %s',selectCuts);
end

fprintf('Processing cuts: %s \n', selectCuts); %[output:1fa9b020]
cuts_list = NG_FFCutsFits.(selectCuts);
if ~iscell(cuts_list)
    cuts_list = {cuts_list};
end
if contains(selectCuts,'Ei200')
    min_Ei = 30;        
    mi = maps_instrument(200,600,'S');
end
if contains(selectCuts,'Ei400')
    min_Ei = 40;            
    mi = maps_instrument(401,600,'S');
end
if contains(selectCuts,'Ei800')
    min_Ei = 70;            
    mi = maps_instrument(786,600,'S');
end
sample=IX_sample(true,[1,0,0],[0,1,0],'cuboid',[0.04,0.03,0.02]);
for j=1:numel(cuts_list) %[output:group:3ed3cc30]
    cuts_list{j} = cuts_list{j}.set_instrument(mi);
    cuts_list{j} = cuts_list{j}.set_sample(sample);
    plot(cuts_list{j}); lz 0 1; keep_figure; %[output:1f0bbdf4]
end %[output:group:3ed3cc30]
dir_name  = "NG";

dE_step = 2; %original energy transfer step data were binned to. No point in going finer
half_dE = 5; % half width of data binning

en_mm = cuts_list{1}.data.img_range(:,4);
en_mm(1) = max(min_Ei,en_mm(1));
%en_mm(1) = 100;
%en_mm(2) = 380;
cut_en = en_mm(1)+half_dE:2*half_dE:(en_mm(2)-half_dE);

cut_dimensions = 1;
NG_FFCutsFits.(selectCuts) = cuts_list;
%%
NG_FFCutsFits = fit_multicutsFF_along_direction(... %[output:group:2e2a27de] %[output:89736575] %[output:05c201fd] %[output:933132a4] %[output:5de7ca12] %[output:941502d1] %[output:5d349d43] %[output:5c5d5e26] %[output:855ccf83] %[output:0e2d4d85] %[output:633e333d] %[output:562debee] %[output:7d68bf4f] %[output:8c525f2a] %[output:0cb163c6] %[output:6ca287af] %[output:8050c21a] %[output:7f06416a] %[output:02c309e6] %[output:861b9502] %[output:7755afed] %[output:96dc44a4] %[output:44141a71] %[output:7fe9dc51] %[output:47fa2fe7] %[output:13ab6ab9] %[output:4467c35d] %[output:5a901590] %[output:263650e4] %[output:225fbf84] %[output:9e5c2ef6] %[output:15228c4e] %[output:5022fdc6] %[output:6af904d5] %[output:379c1ca4] %[output:5a8d31ed] %[output:91266f08] %[output:548551dc] %[output:0ab9a537] %[output:022c6549] %[output:12018227] %[output:7f520bf6] %[output:6b4a36ec] %[output:0898dab5] %[output:05fd66a9] %[output:83b6e6c5] %[output:27e6c5a9] %[output:6a6b5a7b] %[output:6a21c090] %[output:093d94cb] %[output:944cd1d7] %[output:6da09143] %[output:7ad291d2] %[output:49d6af76] %[output:713b4073] %[output:7b944940] %[output:6ec5e138] %[output:9a81a4e8] %[output:3c1cf862] %[output:4cfb1c5f] %[output:9bddf80b] %[output:2cf526d0] %[output:6f9375b7] %[output:1a86117d] %[output:9185d47b] %[output:5604e80c] %[output:667fbdf0] %[output:1c3879dd] %[output:04131446] %[output:6f057968] %[output:0150a4f1] %[output:76018d08] %[output:22021a0a] %[output:111e60ed] %[output:222e41a3] %[output:967425c0] %[output:8c030f49] %[output:93a4f5ed] %[output:5befcf51] %[output:65e124eb] %[output:5894389b] %[output:2ad7538e] %[output:02d01754] %[output:84222fc6] %[output:68ab7a3f] %[output:3404bd6c] %[output:1f794b7d] %[output:14ee2cb0] %[output:18e3922f] %[output:87911335] %[output:45bd376d] %[output:8616173f] %[output:29ca814d] %[output:0d35d3c2] %[output:89bb0c80] %[output:17f6be00]
    NG_FFCutsFits,selectCuts,cut_dimensions,cut_en,dE_step,half_dE,true); %[output:group:2e2a27de] %[output:89736575] %[output:05c201fd] %[output:933132a4] %[output:5de7ca12] %[output:941502d1] %[output:5d349d43] %[output:5c5d5e26] %[output:855ccf83] %[output:0e2d4d85] %[output:633e333d] %[output:562debee] %[output:7d68bf4f] %[output:8c525f2a] %[output:0cb163c6] %[output:6ca287af] %[output:8050c21a] %[output:7f06416a] %[output:02c309e6] %[output:861b9502] %[output:7755afed] %[output:96dc44a4] %[output:44141a71] %[output:7fe9dc51] %[output:47fa2fe7] %[output:13ab6ab9] %[output:4467c35d] %[output:5a901590] %[output:263650e4] %[output:225fbf84] %[output:9e5c2ef6] %[output:15228c4e] %[output:5022fdc6] %[output:6af904d5] %[output:379c1ca4] %[output:5a8d31ed] %[output:91266f08] %[output:548551dc] %[output:0ab9a537] %[output:022c6549] %[output:12018227] %[output:7f520bf6] %[output:6b4a36ec] %[output:0898dab5] %[output:05fd66a9] %[output:83b6e6c5] %[output:27e6c5a9] %[output:6a6b5a7b] %[output:6a21c090] %[output:093d94cb] %[output:944cd1d7] %[output:6da09143] %[output:7ad291d2] %[output:49d6af76] %[output:713b4073] %[output:7b944940] %[output:6ec5e138] %[output:9a81a4e8] %[output:3c1cf862] %[output:4cfb1c5f] %[output:9bddf80b] %[output:2cf526d0] %[output:6f9375b7] %[output:1a86117d] %[output:9185d47b] %[output:5604e80c] %[output:667fbdf0] %[output:1c3879dd] %[output:04131446] %[output:6f057968] %[output:0150a4f1] %[output:76018d08] %[output:22021a0a] %[output:111e60ed] %[output:222e41a3] %[output:967425c0] %[output:8c030f49] %[output:93a4f5ed] %[output:5befcf51] %[output:65e124eb] %[output:5894389b] %[output:2ad7538e] %[output:02d01754] %[output:84222fc6] %[output:68ab7a3f] %[output:3404bd6c] %[output:1f794b7d] %[output:14ee2cb0] %[output:18e3922f] %[output:87911335] %[output:45bd376d] %[output:8616173f] %[output:29ca814d] %[output:0d35d3c2] %[output:89bb0c80] %[output:17f6be00]
cl = NG_FFCutsFits.(selectCuts);
NG_FFCutsFits.(selectCuts) = [cl{:}];

beep
beep
beep
%%

all_fit_par = NG_FFCutsFits.([selectCuts,'_ASJ_fit_par']);
bg_data = extract_bg_par(all_fit_par,[1,2]);
% original slope parameters
pd(bg_data(1));lx(all_fit_par(1).en,all_fit_par(end).en);ly 0 0.3; keep_figure; %[output:445a8e9e]
pd(bg_data(2));lx(all_fit_par(1).en,all_fit_par(end).en);keep_figure %[output:0ef0ca80]
%pd(bg_data(3));lx(fit_res.peak_fit_par(1).en,fit_res.peak_fit_par(end).en);keep_figure;
%pd(bg_data(4));lx(fit_res.peak_fit_par(1).en,fit_res.peak_fit_par(end).en);keep_figure
%%

doc = matlab.desktop.editor.getActive;
doc.save;
thisFile = 'e:\SHARE\Fe\Data\analysis\06_fit_with_AQ0\fit_cutFe_NG.mlx';
targ_file = fullfile(fileparts(thisFile),['fit_cutFe_NG_',selectCuts,'.pdf']);
export(thisFile,targ_file);
%close all;
%end
%%
fit_src_struc = NG_FFCutsFits;
save(CutFitFileNG,"fit_src_struc",'-v7.3')

